from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    groups = []  # Initialize a list to store individual groups

    i = 0
    while i < len(paren_string):
        if paren_string[i] == '(':
            count = 1
            j = i + 1
            while count != 0:
                if paren_string[j] == '(':
                    count += 1
                elif paren_string[j] == ')':
                    count -= 1
                j += 1
            groups.append(paren_string[i:j])  # Step 2: Identify and extract each group of nested parentheses
            i = j
        else:
            i += 1

    result = [group for group in groups]  # Step 3: Separate each group into individual strings and return them as a list
    return result

